SELECT COUNT(*) FROM (
    SELECT a.acct_ref,
        bs.behavioral_anomaly_scores->'automation_spam'->>'bot_likelihood' as bot_score
    FROM accounts a
    JOIN behavioral_scores bs ON bs.acct_beh = a.acct_ref
    JOIN monitoring m ON m.acct_mon = a.acct_ref
    WHERE m.snap_ts = (
        SELECT MAX(m2.snap_ts) FROM monitoring m2 WHERE m2.acct_mon = a.acct_ref
    )
) sub;

SELECT COUNT(*) FROM (
    SELECT DISTINCT ON (m.acct_mon) m.acct_mon, bs.behavioral_anomaly_scores->'automation_spam'->>'bot_likelihood' as bot_score
    FROM monitoring m
    JOIN behavioral_scores bs ON bs.acct_beh = m.acct_mon
    ORDER BY m.acct_mon, m.snap_ts DESC
) sub;

SELECT COUNT(*) FROM (
    SELECT 
        a.acct_ref,
        bs.behavioral_anomaly_scores->'automation_spam'->>'bot_likelihood' as bot_score
    FROM accounts a
    LEFT JOIN behavioral_scores bs ON bs.acct_beh = a.acct_ref
    LEFT JOIN LATERAL (
        SELECT acct_mon, snap_ts FROM monitoring WHERE acct_mon = a.acct_ref ORDER BY snap_ts DESC LIMIT 1
    ) m ON true
) sub;

SELECT jsonb_build_object(
    'pattern_scores', behavioral_anomaly_scores->'pattern_scores',
    'automation_spam', behavioral_anomaly_scores->'automation_spam',
    'commercial_intent_score', behavioral_anomaly_scores->'commercial_intent_score'
) FROM behavioral_scores LIMIT 1;

